-- Sync active storefront assortments for trusted checkout pricing. Retail assortment, descriptions, prices and availability are illustrative sample data.

begin;

update public.stores set is_active=false where id in ('pizza-inn', 'mamas-kitchen', 'burger-yard', 'fresh-basket', 'glam');

update public.products set is_available=false where store_id in ('galitos', 'java', 'cjs-restaurant-nbo-ke', 'artcaffe', 'creamy-inn', 'avon-bitez-nbo', 'carrefour', 'naivas', 'quickmart', 'fruitsdoor-market', 'cleanshelf', 'goodlife', 'nivea', 'pharma-plus', 'flower-shop', 'miniso', 'tamu-deals', 'quick-liquor', 'drinks-corner', 'pizza-inn', 'mamas-kitchen', 'burger-yard', 'fresh-basket', 'glam');

on conflict (id) do update set category_id=excluded.category_id,name=excluded.name,description=excluded.description,cuisine=excluded.cuisine,image_url=excluded.image_url,accent_color=excluded.accent_color,rating=excluded.rating,rating_count=excluded.rating_count,delivery_min_minutes=excluded.delivery_min_minutes,delivery_max_minutes=excluded.delivery_max_minutes,delivery_fee_kes=excluded.delivery_fee_kes,promo_text=excluded.promo_text,badge=excluded.badge,is_active=excluded.is_active;

on conflict (id) do update set store_id=excluded.store_id,name=excluded.name,description=excluded.description,price_kes=excluded.price_kes,old_price_kes=excluded.old_price_kes,image_url=excluded.image_url,tag=excluded.tag,is_available=excluded.is_available;

commit;
